<?php
declare(strict_types=1);
use DigiForgePrintifyConnector\Preparation\{NativePortAdapter,ProtectedPanel};
final class PrintifyCompanionBatch6IntegrationTest extends WP_UnitTestCase {
 public function set_up():void{parent::set_up();require_once dirname(__DIR__,2).'/companion/digiforge-printify-connector/digiforge-printify-connector.php';}
 public function testMissingNativeBridgeDoesNotGrantAdministratorPanelAccess():void{[$s]=(require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();$actor=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($actor);$before=rest_get_server()->get_routes();$cron=_get_cron_array();$context=['version'=>'1.0.0','view'=>'publication','session_fingerprint'=>hash('sha256','synthetic-session'),'csrf_token'=>'synthetic-nonce-123'];self::assertWPError((new ProtectedPanel(DigiForgePrintifyConnector\Plugin::nativePort()))->snapshot($s,$actor,$context));self::assertSame($before,rest_get_server()->get_routes());self::assertSame($cron,_get_cron_array());self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));}
 public function testActualWordPressNonceAndSessionProtectSyntheticPanel():void {
  require_once __DIR__.'/../fixtures/printify-connector/batch6/SyntheticNativeCore.php';[$s]=(require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();$actor=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($actor);$manager=WP_Session_Tokens::get_instance($actor);$token=$manager->create(time()+300);$_COOKIE[LOGGED_IN_COOKIE]=wp_generate_auth_cookie($actor,time()+300,'logged_in',$token);
  try{$core=new SyntheticNativeCore();$core->actor=$actor;$session=hash('sha256',wp_get_session_token());$core->sessionFingerprint=$session;$core->actorCheck=static fn($a)=>get_current_user_id()===$a&&current_user_can('manage_options')&&$manager->verify(wp_get_session_token())&&hash_equals($session,hash('sha256',wp_get_session_token()));$core->nonceCheck=static fn($n)=>wp_verify_nonce($n,'df_native_panel')!==false;$context=$core->context('publication');$context['csrf_token']=wp_create_nonce('df_native_panel');$panel=new ProtectedPanel(new NativePortAdapter($core));self::assertStringContainsString('PUBLICATION_PENDING',$panel->render($s,$actor,$context));$json=$panel->export($s,$actor,$context);self::assertIsString($json);self::assertStringNotContainsString($token,$json);self::assertStringNotContainsString($context['csrf_token'],$json);$bad=$context;$bad['csrf_token']='invalid-nonce';self::assertWPError($panel->snapshot($s,$actor,$bad));$manager->destroy($token);self::assertWPError($panel->snapshot($s,$actor,$context));}finally{unset($_COOKIE[LOGGED_IN_COOKIE]);$manager->destroy_all();}
 }
}
